  window.LEOS_DEBUG={getData:()=>structuredClone(db),seedCounts:()=>Object.fromEntries(GROUPS.map(g=>[g,db.characters.filter(c=>c.group===g).length])),validate:()=>({characters:db.characters.length,relationships:db.relationships.length,events:db.events.length,duplicates:new Set(db.characters.map(x=>x.id)).size!==db.characters.length}),renderTab:t=>{STATE.profileId=null;STATE.tab=t;render();return $('#app').innerHTML},renderProfile:(id,section='Overview')=>{STATE.profileId=id;STATE.profileSection=section;render();return $('#app').innerHTML}};
  if(window.__LEOS_TEST)window.__LEOS_TEST={convertRemote,validateEvent,mergeData,inject:d=>{db=d;render()}};
